import { existsSync, lstatSync, readdirSync, rmdirSync, unlinkSync } from 'node:fs';
import { resolve } from 'node:path';
import type { RegisteredWorkspace } from './workspaceState.js';
import { runGit } from './workspaceState.js';

const generatedMetadata = new Set([
  '.serena/.gitignore',
  '.serena/project.yml',
  '.serena/project.local.yml',
]);

/** Recognize only the known, untracked Serena files generated by Sloop tooling. */
export function generatedSerenaPaths(entry: RegisteredWorkspace): string[] | undefined {
  const status = runGit(['status', '--porcelain=v1', '--untracked-files=all'], entry.executionRoot);
  const statusLines = status ? status.split(/\r?\n/) : [];
  if (!containsOnlyGeneratedMetadata(statusLines)) return undefined;
  const directory = resolve(entry.executionRoot, '.serena');
  try {
    return readGeneratedSerenaPaths(directory, statusLines);
  } catch {
    return missingMetadataPaths(statusLines, directory);
  }
}

function missingMetadataPaths(statusLines: string[], directory: string): string[] | undefined {
  if (statusLines.length === 0 && !existsSync(directory)) return [];
  return undefined;
}

function containsOnlyGeneratedMetadata(statusLines: string[]): boolean {
  return statusLines.every(
    (line) => line.startsWith('?? ') && generatedMetadata.has(line.slice(3)),
  );
}

function readGeneratedSerenaPaths(directory: string, statusLines: string[]): string[] | undefined {
  const directoryInfo = lstatSync(directory);
  if (!isSerenaDirectory(directoryInfo)) return undefined;
  const names = readdirSync(directory).sort();
  if (!isSafeMetadataShape(names, statusLines)) return undefined;
  if (!areSafeMetadataEntries(directory, names)) return undefined;
  return names.map((name) => `.serena/${name}`);
}

function isSerenaDirectory(info: ReturnType<typeof lstatSync>): boolean {
  return Boolean(info?.isDirectory() && !info.isSymbolicLink());
}

function isSafeMetadataShape(names: string[], statusLines: string[]): boolean {
  return hasKnownMetadataNames(names) && !hasUnexpectedMetadataPath(names, statusLines);
}

function hasKnownMetadataNames(names: string[]): boolean {
  const knownNames = ['.gitignore', 'project.yml', 'project.local.yml', 'memories'];
  return names.every((name) => knownNames.includes(name));
}

function hasUnexpectedMetadataPath(names: string[], statusLines: string[]): boolean {
  const expectedPaths = names.map((name) => `.serena/${name}`);
  return statusLines.some((line) => !expectedPaths.includes(line.slice(3)));
}

function areSafeMetadataEntries(directory: string, names: string[]): boolean {
  for (const name of names) {
    if (!isSafeMetadataEntry(resolve(directory, name), name)) return false;
  }
  return true;
}

function isSafeMetadataEntry(path: string, name: string): boolean {
  const info = lstatSync(path);
  if (name === 'memories')
    return info.isDirectory() && !info.isSymbolicLink() && readdirSync(path).length === 0;
  return info.isFile() && !info.isSymbolicLink();
}

/** Remove recognized generated metadata only after the full shape is verified. */
export function removeGeneratedSerenaMetadata(entry: RegisteredWorkspace): boolean {
  const paths = generatedSerenaPaths(entry);
  if (paths === undefined) return false;
  if (!paths.length) return true;
  removeMetadataPaths(entry.executionRoot, paths);
  return true;
}

function removeMetadataPaths(root: string, paths: string[]): void {
  for (const path of paths) {
    if (path === '.serena/memories') rmdirSync(resolve(root, path));
    else unlinkSync(resolve(root, path));
  }
  rmdirSync(resolve(root, '.serena'));
}
